INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(83414006, 'Vision HERO Poisoner', '幻影－英雄 投毒者', 'V・HERO ポイズナー', 'Effect Monster', 'Warrior', 'DARK', 3, 900, 700, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己因战斗·效果受到伤害的场合才能发动。墓地的这张卡当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续陷阱卡使用的场合，双方的主要阶段，把自己场上1只「英雄」怪兽解放才能发动。这张卡特殊召唤。 ③：这张卡从魔法与陷阱区域的特殊召唤成功的场合才能发动。选场上1只怪兽，那个攻击力变成一半。'),
(46759931, 'Vision HERO Trinity', '幻影－英雄 三位一体', 'V・HERO トリニティー', 'Fusion Monster', 'Warrior', 'DARK', 8, 2500, 2000, '「英雄」怪兽×3 ①：这张卡不能直接攻击。 ②：这张卡融合召唤时适用。这张卡的攻击力直到回合结束时变成原本攻击力的2倍。 ③：融合召唤的这张卡在同1次的战斗阶段中可以作3次攻击。'),
(27780618, 'Vision HERO Vyon', '幻影－英雄 拜昂', 'V・HERO ヴァイオン', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只「英雄」怪兽送去墓地。 ②：1回合1次，从自己墓地把1只「英雄」怪兽除外才能发动。从卡组把1张「融合」加入手卡。'),
(82697428, 'Vision HERO Witch Raider', '幻影－英雄 突袭魔女', 'V・HERO ウィッチ・レイド', 'Effect Monster', 'Warrior', 'DARK', 8, 2700, 1900, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的陷阱卡解放。 ①：这张卡召唤成功时才能发动。对方场上的魔法·陷阱卡全部破坏。这个效果发动的回合，自己不是「英雄」怪兽不能特殊召唤。'),
(19186123, 'Vision Release', '幻影解放', '幻影解放', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的魔法与陷阱区域1张「幻影英雄」怪兽卡为对象才能发动。那张卡特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「幻影英雄」怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(98396890, 'Vision Resonator', '视界共鸣者', 'ヴィジョン・リゾネーター', 'Tuner Monster', 'Fiend', 'DARK', 2, 400, 400, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场上有5星以上的暗属性怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把有「红莲魔龙」的卡名记述的1张魔法·陷阱卡加入手卡。'),
(35659410, 'Vision with Eyes of Blue', '青之眼的幻出', '青き眼の幻出', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡也能把手卡1只「青眼白龙」给人观看来发动。那个场合，从手卡把1只怪兽特殊召唤。 ②：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽回到持有者手卡。那之后，可以让回到手卡的卡的原本卡名的以下效果适用。 ●「青眼白龙」：从手卡把1只怪兽特殊召唤。 ●那以外：从手卡把1只「青眼」怪兽特殊召唤。'),
(52575195, 'Vivid Knight', '机灵兔骑士', 'ビビット騎士', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1700, 800, '自己场上的兽战士族·光属性怪兽1只成为对方的卡的效果的对象时或者成为对方怪兽的攻击对象时才能发动。成为对象的自己怪兽直到下次的自己的准备阶段时从游戏中除外，这张卡从手卡特殊召唤。'),
(7608148, 'Vivid Tail', '炫亮尾迹', 'Vivid Tail', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1张卡为对象才能发动。那张卡回到持有者手卡。 ②：这张卡在墓地存在的场合，以自己场上1张表侧表示的卡为对象才能发动。这张卡在自己场上盖放，那张表侧表示的卡回到持有者手卡。这个效果盖放的这张卡从场上离开的场合除外。这个回合，自己不能把这个效果回到手卡的卡以及那些同名卡的效果发动。'),
(101303085, 'Vodnika the Fountain Spirit', NULL, NULL, 'Effect Monster', 'Aqua', 'LIGHT', 10, 2000, 2100, NULL),
(41773061, 'Voici la Carte (Today''s Menu)', 'Voici la Carte～请看菜单～', 'Voici la Carte～メニューはこちら～', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把2只卡名不同的「新式魔厨」怪兽给对方观看，对方从那之中选1只。那1只怪兽加入自己手卡，剩余回到卡组。那之后，可以从自己的卡组·墓地选这个效果加入手卡的怪兽种族的1张以下的卡加入手卡。 ●兽战士族：「鱼料理的食谱」 ●战士族：「肉料理的食谱」'),
(7337976, 'Void Apocalypse', '炼狱的灾天', '煉獄の災天', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：丢弃1张手卡才能发动。从卡组把1只恶魔族怪兽送去墓地。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。把最多有从额外卡组特殊召唤的对方场上的怪兽数量的「狱火机」怪兽从手卡·卡组送去墓地（同名卡最多1张）。'),
(96235944, 'Void Breach', '炼狱的决界', '煉獄の決界', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「狱火机」怪兽的攻击力上升自己的除外状态的「狱火机」怪兽数量×100。 ②：自己场上的怪兽不存在的场合或者只有恶魔族怪兽的场合，可以从以下效果选择1个发动。 ●自己的除外状态的1只「狱火机」怪兽加入手卡。 ●从手卡把1只「狱火机」怪兽无视召唤条件特殊召唤。'),
(45313724, 'Void Cauldron', '炼狱之釜', '煉獄の釜', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的「永火」怪兽或者龙族·暗属性·8星的同调怪兽被对方的效果破坏的场合，可以作为代替把自己墓地1张「永火」卡除外。 ②：自己手卡不是0张的场合，这张卡送去墓地。'),
(34822850, 'Void Expansion', '炼狱的泛滥', '煉獄の氾爛', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己准备阶段才能发动。在自己场上把1只「狱火机衍生物」（恶魔族·炎·1星·攻/守0）特殊召唤。 ②：「狱火机」怪兽用自身的方法特殊召唤的场合，从自己场上也能把「狱火机」怪兽除外。 ③：对方怪兽不能选择在自己场上的「狱火机」怪兽之内除等级最高的怪兽以外的「狱火机」怪兽作为攻击对象，对方不能以此类作为效果的对象。'),
(31548814, 'Void Feast', '炼狱的狂宴', '煉獄の狂宴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己的手卡·场上（表侧表示）1张「炼狱」魔法·陷阱卡送去墓地才能发动。等级合计直到变成8星为止，从卡组把最多3只「狱火机」怪兽无视召唤条件特殊召唤。'),
(31444249, 'Void Imagination', '炼狱的虚梦', '煉獄の虚夢', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的原本等级是2星以上的「狱火机」怪兽等级变成1星，那些怪兽给与对方的战斗伤害变成一半。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「狱火机」融合怪兽融合召唤。从额外卡组特殊召唤的怪兽只有对方场上才存在的场合，自己卡组的怪兽也能有最多6只作为融合素材。'),
(94432298, 'Void Launch', '壳醒的炼狱', '殻醒する煉獄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己准备阶段才能发动。从卡组把最多2只「狱火机」怪兽送去墓地。 ②：自己场上有「狱火机」怪兽以外的怪兽存在的场合这张卡送去墓地。'),
(61345801, 'Void Liberation', '炼狱的乖放', '煉獄の乖放', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1张「影依」卡给对方观看才能发动。和给人观看的卡种类（怪兽·魔法·陷阱）不同的2张「影依」卡从卡组加入手卡（相同种类最多1张）。那之后，选自己1张手卡丢弃。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地把1只「狱火机」怪兽加入手卡。'),
(81020646, 'Void Ogre Dragon', '炼狱龙 食人魔龙鬼', '煉獄龍 オーガ・ドラグーン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 3000, '暗属性调整＋调整以外的怪兽1只以上 自己手卡是0张的场合，1回合1次，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(61965407, 'Void Purification', '溯洸的炼狱', '遡洸する煉獄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方准备阶段，以自己墓地1只「狱火机」怪兽为对象才能发动。那只怪兽加入手卡。 ②：自己准备阶段，以自己的除外状态的1只「狱火机」怪兽为对象才能发动。那只怪兽回到墓地。 ③：自己场上有「狱火机」怪兽以外的怪兽存在的场合这张卡送去墓地。'),
(60830240, 'Void Reignition', '炽动的炼狱', '熾動する煉獄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果在决斗中只能使用1次。 ①：把手卡1只「狱火机」怪兽或1张「炼狱」魔法·陷阱卡给对方观看才能发动。自己手卡全部丢弃。那之后，自己抽出丢弃的数量。 ②：自己场上的怪兽不存在的场合或者只有恶魔族怪兽的场合，把这个回合没有送去墓地的这张卡从墓地除外，以自己的除外状态的最多11只「狱火机」怪兽为对象才能发动（同名卡最多1张）。那些怪兽回到墓地。'),
(8437145, 'Void Seer', '炼狱的死徒', '煉獄の死徒', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「狱火机」怪兽为对象才能发动。这个回合，那只自己怪兽不受对方的效果影响。 ②：自己场上的「狱火机」怪兽被效果破坏的场合，可以作为那些「狱火机」怪兽之内的1只的代替而把墓地的这张卡除外。'),
(1005587, 'Void Trap Hole', '炼狱落穴', '煉獄の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把攻击力2000以上的怪兽特殊召唤时才能发动。选那1只攻击力2000以上的怪兽，把效果无效并破坏。'),
(78748366, 'Void Vanishment', '炼狱的消华', '煉獄の消華', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：丢弃1张手卡才能发动。从卡组把「炼狱的消华」以外的1张「炼狱」魔法·陷阱卡加入手卡。这个效果的发动后，直到回合结束时自己不是「狱火机」怪兽不能召唤·特殊召唤。 ②：自己的「狱火机」怪兽和对方怪兽进行战斗的伤害计算后，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。那些进行战斗的双方怪兽除外。'),
(38026562, 'Vola-Chemicritter Methydraco', '超化合兽 甲醇双面兽', '超化合獣メタン・ハイド', 'XYZ Monster', 'Beast-Warrior', 'FIRE', 8, 3000, 3000, '8星二重怪兽×2 ①：这张卡超量召唤成功时，以自己墓地1只二重怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要持有超量素材的这张卡在怪兽区域存在，对方不能把自己场上的二重怪兽作为攻击对象，也不能作为效果的对象。 ③：二重怪兽召唤成功时，把这张卡1个超量素材取除才能发动。对方必须把自身的手卡·场上1张卡送去墓地。'),
(81020140, 'Volcanic Blaster', '火山转轮', 'ヴォルカニック・リボルバー', 'Effect Monster', 'Pyro', 'FIRE', 3, 1200, 600, '这张卡被战斗破坏送去墓地时，可以让卡组的1只名字带有「火山」的怪兽在卡组最上面放置。'),
(85250352, 'Volcanic Blaze Accelerator', '火山烈焰加农炮', 'ヴォルカニック・ブレイズ・キャノン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '从手卡·卡组·场上（表侧表示）把1张「烈焰加农炮」送去墓地才能把这张卡发动。 ①：「火山烈焰加农炮」在自己场上只能有1张表侧表示存在。 ②：1回合1次，自己主要阶段才能发动。从手卡把1只「火山」怪兽特殊召唤。 ③：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。从卡组把1只炎族·1星怪兽送去墓地，作为对象的怪兽破坏。'),
(300302042, 'Volcanic Cannon', NULL, NULL, 'Skill Card', 'Axel Brodie', NULL, NULL, NULL, NULL, NULL),
(66436257, 'Volcanic Counter', '火山反击兽', 'ヴォルカニック・カウンター', 'Effect Monster', 'Pyro', 'FIRE', 3, 300, 1300, '自己受到战斗伤害时，墓地存在的这张卡从游戏中除外。那个时候，自己墓地有「火山反击兽」以外的炎属性怪兽存在的场合，给与对方基本分和自己受到的战斗伤害相同的伤害。'),
(32543380, 'Volcanic Doomfire', '火山恶魔', 'ヴォルカニック・デビル', 'Effect Monster', 'Pyro', 'FIRE', 8, 3000, 1800, '这张卡不能通常召唤。把自己场上1张表侧表示的「烈焰加农炮-三叉戟式」送去墓地的场合可以特殊召唤。 ①：对方战斗阶段中，可以攻击的对方的攻击表示怪兽必须向这张卡作出攻击。 ②：这张卡战斗破坏怪兽送去墓地的场合发动。对方场上的怪兽全部破坏，给与对方破坏数量×500伤害。'),
(58143766, 'Volcanic Emission', '火山喷出', 'ヴォルカニック・エミッション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从卡组选1只「火山」怪兽加入手卡或无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。 ●以场上1只炎族怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。以自己场上的怪兽为对象发动的场合，这个效果给与的伤害变成一半。'),
(46412900, 'Volcanic Emperor', '火山帝皇', 'ヴォルカニック・エンペラー', 'Effect Monster', 'Pyro', 'FIRE', 8, 3100, 2400, '这张卡不能通常召唤。从自己的场上（表侧表示）·墓地把3只炎族怪兽或1张「烈焰加农炮」卡除外的场合才能从手卡·墓地特殊召唤。自己对「火山帝皇」1回合只能有1次特殊召唤。 ①：这个方法让这张卡特殊召唤时才能发动。给与对方为除外状态的炎族怪兽数量×500伤害。那之后，可以从卡组把1张「火山」陷阱卡在自己场上盖放。 ②：每次对方把怪兽特殊召唤给与对方500伤害。'),
(42175079, 'Volcanic Eruption', '大喷火', '大噴火', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有「侏罗纪世界」存在的场合，自己的结束阶段时才能发动。场上的卡全部破坏。'),
(54514594, 'Volcanic Hammerer', '火山重锤', 'ヴォルカニック・ハンマー', 'Effect Monster', 'Pyro', 'FIRE', 5, 2400, 1500, '可以给与对方基本分自己墓地存在的名字带有「火山」的怪兽卡数量×200的数值的伤害。这个效果1回合只能使用1次。这个效果发动的场合，这个回合这张卡不能攻击。'),
(84138874, 'Volcanic Inferno', '火山业火', 'ヴォルカニック・インフェルノ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把场上的怪兽的效果发动时，从自己墓地把1只炎族怪兽除外才能发动。给与对方500伤害。把「火山」怪兽除外发动的场合，可以再把那个发动的效果无效。 ②：对方结束阶段，以自己的墓地·除外状态的最多2只「火山」怪兽为对象才能发动。那些怪兽用喜欢的顺序回到卡组下面。'),
(63014935, 'Volcanic Queen', '火山女王', 'ヴォルカニック・クイーン', 'Effect Monster', 'Pyro', 'FIRE', 6, 2500, 1200, '这张卡不能通常召唤。把对方场上1只怪兽解放的场合可以在对方场上特殊召唤。把这张卡特殊召唤的回合，自己不能通常召唤。 ①：1回合1次，把自己场上1张其他卡送去墓地才能发动。给与对方1000伤害。 ②：自己结束阶段发动。自己场上1只其他怪兽解放或自己受到1000伤害。'),
(33112041, 'Volcanic Rat', '火山鼠', 'ヴォルカニック・ラット', 'Normal Monster', 'Pyro', 'FIRE', 1, 500, 500, '灼热的火山地带生活的鼠类变种。拥有任何高温都能够抵抗的身体。'),
(33725271, 'Volcanic Recharge', '火山充能', 'ヴォルカニック・チャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地存在的最多3张名字带有「火山」的怪兽卡回到卡组。'),
(59805313, 'Volcanic Rimfire', '火山缘发弹', 'ヴォルカニック・リムファイア', 'Effect Monster', 'Pyro', 'FIRE', 1, 300, NULL, '①：这张卡被送去墓地的场合，可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●墓地的这张卡除外，从卡组把「火山缘发弹」以外的1只「火山」怪兽送去墓地。 ●从自己的场上（表侧表示）·墓地把1张「烈焰加农炮」卡除外，从手卡·卡组把1张「烈焰加农炮」永续魔法·永续陷阱卡在自己场上表侧表示放置。'),
(76459806, 'Volcanic Rocket', '火山火箭弹', 'ヴォルカニック・ロケット', 'Effect Monster', 'Pyro', 'FIRE', 4, 1900, 1400, '①：这张卡召唤·反转召唤·特殊召唤时才能发动。从自己的卡组·墓地把1张「烈焰加农炮」卡加入手卡。'),
(69750546, 'Volcanic Scattershot', '火山鹿弹', 'ヴォルカニック・バックショット', 'Effect Monster', 'Pyro', 'FIRE', 2, 500, NULL, '①：这张卡被送去墓地的场合发动。给与对方500伤害。 ②：这张卡被「烈焰加农炮」卡的效果送去墓地的场合，从手卡·卡组把2只「火山鹿弹」送去墓地才能发动。对方场上的怪兽全部破坏。'),
(33365932, 'Volcanic Shell', '火山性子弹', 'ヴォルカニック・バレット', 'Effect Monster', 'Pyro', 'FIRE', 1, 100, NULL, '①：这张卡在墓地存在的场合，1回合1次，支付500基本分才能发动。这张卡在墓地存在的场合，从卡组把1只「火山弹」加入手卡。'),
(17415895, 'Volcanic Slicer', '火山利刃', 'ヴォルカニック・エッジ', 'Effect Monster', 'Pyro', 'FIRE', 4, 1800, 1200, '可以给与对方基本分500分伤害。这个效果1回合只能使用1次。这个效果发动的场合，这个回合这张卡不能攻击。'),
(22411609, 'Volcanic Trooper', '火山骑兵', 'ヴォルカニック・トルーパー', 'Effect Monster', 'Pyro', 'FIRE', 3, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「火山骑兵」以外的1张「火山」卡加入手卡。 ②：丢弃1张手卡才能发动。在对方场上把1只「炸弹衍生物」（炎族·炎·1星·攻/守1000）特殊召唤。这衍生物被破坏时那个控制者受到500伤害。'),
(38694052, 'Voloferniges, the Darkest Dragon Doomrider', '黑熔龙骑 沃尔尼吉斯', '黒熔龍騎ヴォルニゲシュ', 'XYZ Monster', 'Dragon', 'DARK', 7, 2500, 2100, '7星怪兽×2 ①：1回合1次，把这张卡2个超量素材取除，以场上1张表侧表示的卡为对象才能发动。那张卡破坏。这个效果把怪兽破坏的场合，可以选自己场上1只表侧表示怪兽，那个攻击力直到下个回合的结束时上升破坏的怪兽的原本的等级·阶级的数值×300。这个效果发动的回合，这张卡不能攻击。这张卡有龙族怪兽在作为超量素材的场合，这个效果在对方回合也能发动。'),
(20951752, 'Voltanis the Adjudicator', '裁决下达者-伏尔泰尼斯', '裁きを下す者－ボルテニス', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 1400, '自己的反击陷阱发动成功的场合，把自己场上全部怪兽作祭品可以特殊召唤。这个方法特殊召唤成功的场合，可以把最多有作祭品的天使族怪兽的数量的对方场上的卡破坏。'),
(18585765, 'Voltester', '伏特测士', 'ボルテスター', 'Effect Monster', 'Thunder', 'DARK', 7, 2500, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡在连接怪兽所连接区特殊召唤的场合发动。和这张卡成为连接状态的连接怪兽全部破坏。并且再重复「破坏的连接怪兽的所连接区的怪兽也全部破坏」处理。（这个效果不会让这张卡被破坏。）'),
(13995824, 'Voltic Bicorn', '流电双角兽', 'ボルテック・バイコーン', 'Synchro Monster', 'Beast', 'LIGHT', 7, 2500, 2000, '兽族调整＋调整以外的怪兽1只以上 这张卡被对方破坏的场合，双方玩家从卡组上面把7张卡送去墓地。'),
(93151201, 'Voltic Kong', '雷电金刚', 'ボルテック・コング', 'Effect Monster', 'Beast', 'LIGHT', 4, 1800, 1000, '这张卡给与对方基本分战斗伤害时，把自己场上表侧表示存在的光属性怪兽数量的卡从对方卡组上面送去墓地。'),
(14898066, 'Vorse Raider', '血腥魔兽人', 'ブラッド・ヴォルス', 'Normal Monster', 'Beast-Warrior', 'DARK', 4, 1900, 1200, '做尽坏事并以此为乐的魔兽人。手上的斧子经常沾满鲜血。'),
(25373678, 'Vortex the Whirlwind', '旋风之沃泰克斯', '旋風のボルテクス', 'Synchro Monster', 'Winged Beast', 'WIND', 5, 2100, 700, '调整＋调整以外的鸟兽族怪兽1只以上 这张卡被战斗破坏送去墓地时，可以从自己卡组把1只4星以下的鸟兽族怪兽特殊召唤。'),
(7736719, 'Vortex Trooper', '空气循环机', 'エア・サーキュレーター', 'Effect Monster', 'Aqua', 'WIND', 3, NULL, 600, '①：这张卡召唤成功时才能发动。让2张手卡回到卡组洗切。那之后，自己从卡组抽2张。 ②：这张卡被破坏的场合发动。自己从卡组抽1张。'),
(739444, 'Vorticular Drumgon', '弹匣龙', 'マガジンドラムゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1000, NULL, '龙族·暗属性怪兽3只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。自己从卡组抽1张。 ②：这张卡的①的效果适用的回合只要这张卡在怪兽区域存在，作为这张卡所连接区的没有使用的怪兽区域不能使用。'),
(75311421, 'Votis', '布提斯', 'ボティス', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, 1900, '①：这张卡召唤成功时才能发动。从自己卡组上面把3张卡翻开。那之中有怪兽的场合，可以通过把那之内的1只除外来把那1只同名怪兽从卡组以及翻开的卡之中加入手卡。剩下的卡回到卡组。 ②：通常召唤的这张卡被送去墓地的回合的结束阶段才能发动。从自己卡组上面把3张卡翻开，用喜欢的顺序回到卡组上面。'),
(36974120, 'Vouiburial, the Dragon Undertaker', '龙葬主－维尔殓', '竜葬主－ヴィブリアル', 'Effect Monster', 'Illusion', 'DARK', 10, 3000, NULL, '①：怪兽在主要阶段从对方场上送去墓地的场合，可以把以这张卡在哪里存在来对应的以下效果发动（这个卡名的以下效果1回合各能使用1次）。 ●手卡：这张卡特殊召唤。 ●场上：对方场上1只效果怪兽的攻击力下降1500。这个效果让攻击力变成0的场合，可以再把那只怪兽破坏。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(77387463, 'Vulcan Dragni the Cubic King', '方界帝 神火之德拉耆尼', '方界帝ヴァルカン・ドラグニー', 'Effect Monster', 'Fairy', 'FIRE', 3, NULL, NULL, '这张卡不能通常召唤。把自己场上2只「方界」怪兽送去墓地的场合可以特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升1600。 ②：这张卡从手卡的特殊召唤成功的场合发动。给与对方800伤害。 ③：这张卡战斗的伤害步骤结束时，以自己墓地最多3只「方界胤 毗贾姆」为对象才能发动。这张卡送去墓地，作为对象的怪兽特殊召唤。那之后，可以从卡组把1只「方界超帝 死雷之印陀罗」加入手卡。'),
(98012938, 'Vulcan the Divine', '兽神 武尔坎', '獣神ヴァルカン', 'Synchro Monster', 'Beast-Warrior', 'FIRE', 6, 2000, 1600, '调整＋调整以外的怪兽1只以上 这个卡名的效果1回合只能使用1次。 ①：这张卡同调召唤的场合，以自己以及对方场上的表侧表示卡各1张为对象发动。那些自己以及对方的表侧表示卡回到手卡。这个回合，自己不能把这个效果回到手卡的卡以及那些同名卡的效果发动。'),
(58354899, 'Vulcarrion the Rotting Phoenix', '腐死鸟 死尸秃鹫', '腐死鳥ヴァルコプス', 'Tuner Monster', 'Zombie', 'DARK', 4, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有不死族怪兽存在的场合才能发动。这张卡特殊召唤。 ②：自己主要阶段才能发动。场上的这张卡回到手卡。那之后，可以从手卡把1只不死族怪兽特殊召唤。'),
(93683815, 'Vulmina, Statue of the Sacred Dragon', '圣龙布尔米纳像', '聖竜ヴルミナ像', 'Pendulum Effect Monster', 'Dragon', 'LIGHT', 2, 200, 1800, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡在自己的灵摆区域放置，那只对方怪兽回到手卡。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(58859575, 'VW-Tiger Catapult', 'VW-强击虎', 'VW－タイガー・カタパルト', 'Fusion Monster', 'Machine', 'LIGHT', 6, 2000, 2100, '「V-喷气虎」＋「W-弹射飞翼」 把自己场上的上记卡除外的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：丢弃1张手卡，以对方场上1只怪兽为对象才能发动。那只对方怪兽的表示形式变更。这个时候，反转怪兽的效果不发动。'),
(84243274, 'VWXYZ-Dragon Catapult Cannon', 'VWXYZ-神龙强击炮', 'VWXYZ－ドラゴン・カタパルトキャノン', 'Fusion Monster', 'Machine', 'LIGHT', 8, 3000, 2800, '「VW-强击虎」＋「XYZ-神龙炮」 把自己场上的上记卡除外的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：1回合1次，以对方场上1张卡为对象才能发动。那张对方的卡除外。 ②：这张卡向对方怪兽攻击宣言时，以那1只攻击对象怪兽为对象才能发动。那只攻击对象怪兽的表示形式变更。这个时候，反转怪兽的效果不发动。'),
(56768355, 'Vylon Alpha', '阿尔法大日', 'ヴァイロン・アルファ', 'Synchro Monster', 'Machine', 'LIGHT', 9, 2200, 1100, '名字带有「大日」的调整＋调整以外的怪兽1只以上 这张卡同调召唤成功时，可以选择自己墓地存在的1张装备魔法卡给这张卡装备。有装备卡装备的这张卡不会被装备卡以外的魔法·陷阱卡的效果破坏。'),
(13220032, 'Vylon Charger', '大日充能者', 'ヴァイロン・チャージャー', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 1000, '自己场上表侧表示存在的光属性怪兽的攻击力上升这张卡装备的装备卡数量×300的数值。'),
(55046718, 'Vylon Component', '大日元件', 'ヴァイロン・コンポーネント', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「大日」的怪兽才能装备。装备怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。场上表侧表示存在的这张卡被送去墓地的场合，可以从自己卡组把1张名字带有「大日」的魔法卡加入手卡。'),
(41431329, 'Vylon Cube', '大日立方体', 'ヴァイロン・キューブ', 'Tuner Monster', 'Machine', 'LIGHT', 3, 800, 800, '这张卡被光属性怪兽的同调召唤使用送去墓地的场合，可以从自己卡组选择1张装备魔法卡加入手卡。'),
(45215453, 'Vylon Delta', '德尔塔大日', 'ヴァイロン・デルタ', 'Synchro Monster', 'Fairy', 'LIGHT', 7, 1700, 2800, '调整＋调整以外的光属性怪兽1只以上 这张卡表侧守备表示存在的场合，自己的结束阶段时可以从自己卡组选择1张装备魔法卡加入手卡。'),
(39987164, 'Vylon Disigma', '双西格马大日', 'ヴァイロン・ディシグマ', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 2500, 2100, '4星怪兽×3 1回合1次，可以把这张卡1个超量素材取除，选择对方场上表侧攻击表示存在的1只效果怪兽当作装备卡使用给这张卡装备。这张卡和与这个效果装备的怪兽卡相同属性的怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。'),
(92035412, 'Vylon Element', '大日元素', 'ヴァイロン・エレメント', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「大日」的装备卡被破坏时，可以从自己卡组把最多和破坏数量相同数量的名字带有「大日」的调整在自己场上特殊召唤。把这个效果特殊召唤的怪兽作为同调素材的场合，不是名字带有「大日」的怪兽的同调召唤不能使用。'),
(75779210, 'Vylon Epsilon', '艾普西龙大日', 'ヴァイロン・エプシロン', 'Synchro Monster', 'Fairy', 'LIGHT', 8, 2800, 1200, '光属性调整＋调整以外的怪兽1只以上 这张卡装备的装备卡不能成为魔法·陷阱·效果怪兽的效果的对象。1回合1次，可以把这张卡装备的1张装备卡送去墓地，选择对方场上存在的1只怪兽破坏。'),
(90592429, 'Vylon Filament', '大日细丝', 'ヴァイロン・フィラメント', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「大日」的怪兽才能装备。装备怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。场上表侧表示存在的这张卡被送去墓地的场合，可以从自己卡组把1张名字带有「大日」的魔法卡加入手卡。'),
(168917, 'Vylon Hept', '哈普托大日', 'ヴァイロン・ハプト', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 800, '1回合1次，可以选择当作装备卡使用在自己场上存在的1张名字带有「大日」的怪兽卡表侧守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合从游戏中除外。'),
(74657662, 'Vylon Material', '大日素材', 'ヴァイロン・マテリアル', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「大日」的怪兽才能装备。装备怪兽的攻击力上升600。场上表侧表示存在的这张卡被送去墓地的场合，可以从卡组把1张名字带有「大日」的魔法卡加入手卡。'),
(41858121, 'Vylon Matter', '大日物质', 'ヴァイロン・マター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的3张装备魔法卡发动。选择的卡加入卡组洗切，从以下效果选择1个适用。 ●从自己卡组抽1张卡。 ●对方场上存在的1张卡破坏。'),
(5237827, 'Vylon Ohm', '欧姆大日', 'ヴァイロン・オーム', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 200, '这张卡召唤成功时，选择自己墓地存在的1张装备魔法卡从游戏中除外。下次的自己的准备阶段时把那张卡加入手卡。'),
(93157004, 'Vylon Omega', '欧米伽大日', 'ヴァイロン・オメガ', 'Synchro Monster', 'Fairy', 'LIGHT', 10, 3200, 1900, '调整2只＋调整以外的名字带有「大日」的怪兽1只 这张卡同调召唤成功时，场上表侧表示存在的通常召唤的怪兽全部破坏。1回合1次，可以选择自己墓地存在的1只名字带有「大日」的怪兽当作装备卡使用给这张卡装备。效果怪兽的效果发动时，可以把这张卡装备的1张装备卡送去墓地让那个发动无效并破坏。'),
(47228077, 'Vylon Pentachloro', '大日五胞体', 'ヴァイロン・ペンタクロ', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 500, 400, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的名字带有「大日」的怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽战斗破坏对方怪兽的场合，可以选择对方场上1张卡破坏。（1只怪兽可以装备的同盟最多1张。装备怪兽被破坏的场合，作为代替把这张卡破坏。）'),
(65659181, 'Vylon Polytope', '大日多胞体', 'ヴァイロン・ポリトープ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择当作装备卡使用在自己场上存在的名字带有「大日」的怪兽卡任意数量发动。选择的卡表侧守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合从游戏中除外。'),
(74064212, 'Vylon Prism', '大日棱柱体', 'ヴァイロン・プリズム', 'Tuner Monster', 'Thunder', 'LIGHT', 4, 1500, 1500, '这张卡从怪兽卡区域上送去墓地的场合，可以支付500基本分，把这张卡当作装备卡使用给自己场上表侧表示存在的1只怪兽装备。这张卡的装备怪兽进行战斗的场合，装备怪兽的攻击力在伤害步骤内上升1000。'),
(1644289, 'Vylon Segment', '大日断片', 'ヴァイロン・セグメント', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「大日」的怪兽才能装备。装备怪兽不会成为对方的陷阱·效果怪兽的效果的对象。场上表侧表示存在的这张卡被送去墓地的场合，可以从自己卡组把1张名字带有「大日」的魔法卡加入手卡。'),
(48370501, 'Vylon Sigma', '西格马大日', 'ヴァイロン・シグマ', 'Synchro Monster', 'Fairy', 'LIGHT', 7, 1800, 1000, '光属性调整＋调整以外的光属性怪兽1只以上 自己场上没有这张卡以外的怪兽存在的场合，这张卡的攻击宣言时才能发动。从自己卡组选择1张装备魔法卡给这张卡装备。'),
(40619741, 'Vylon Soldier', '大日士兵', 'ヴァイロン・ソルジャー', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 1000, '这张卡的攻击宣言时，可以选择最多有这张卡装备的装备卡数量的对方场上存在的怪兽，把表示形式变更。'),
(75886890, 'Vylon Sphere', '大日球体', 'ヴァイロン・スフィア', 'Tuner Monster', 'Machine', 'LIGHT', 1, 400, 400, '①：这张卡从怪兽区域送去墓地的场合，支付500基本分，以自己场上1只表侧表示怪兽为对象才能发动。这张卡当作装备卡使用给那只自己怪兽装备。 ②：把当作装备卡使用的这张卡送去墓地，以这张卡装备过的怪兽可以装备的自己墓地1张装备魔法卡为对象才能发动。这张卡装备过的怪兽把作为对象的卡装备。'),
(38679204, 'Vylon Stella', '大日星状体', 'ヴァイロン・ステラ', 'Tuner Monster', 'Fairy', 'LIGHT', 3, 1400, 200, '这张卡从怪兽卡区域上送去墓地的场合，可以支付500基本分，把这张卡当作装备卡使用给自己场上表侧表示存在的1只怪兽装备。和这张卡的装备怪兽进行战斗的对方怪兽在那次伤害步骤结束时破坏。'),
(10712320, 'Vylon Stigma', '斯蒂格马大日', 'ヴァイロン・スティグマ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1000, '1回合1次，可以把自己场上表侧表示存在的1张名字带有「大日」的装备卡转换给1只别的能变成正确对象的怪兽。这个效果在对方回合也能发动。'),
(84313685, 'Vylon Tesseract', '大日超立方体', 'ヴァイロン・テセラクト', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 800, 600, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的名字带有「大日」的怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽战斗破坏对方怪兽的场合，可以从自己墓地选择1只4星以下的名字带有「大日」的怪兽特殊召唤。（1只怪兽可以装备的同盟最多1张。装备怪兽被破坏的场合，作为代替把这张卡破坏。）'),
(1281505, 'Vylon Tetra', '大日四面体', 'ヴァイロン・テトラ', 'Tuner Monster', 'Machine', 'LIGHT', 2, 900, 900, '这张卡从怪兽卡区域上送去墓地的场合，可以支付500基本分，把这张卡当作装备卡使用给自己场上表侧表示存在的1只怪兽装备。这张卡的装备怪兽被破坏的场合，可以作为代替把这张卡破坏。'),
(87836938, 'Vylon Vanguard', '大日前锋', 'ヴァイロン・ヴァンガード', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1000, '这张卡被卡的效果破坏送去墓地时，可以从自己卡组抽出这张卡装备的装备卡数量的卡。'),
(90075978, 'W Nebula Meteorite', 'W星云陨石', 'W星雲隕石', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上里侧表示存在的怪兽全部变成表侧守备表示。这个回合的结束阶段时自己场上表侧表示存在的爬虫类族·光属性怪兽全部变成里侧守备表示，自己从卡组抽出那个数量的卡。那之后，可以从自己卡组把1只7星以上的爬虫类族·光属性怪兽特殊召唤。'),
(96300057, 'W-Wing Catapult', 'W-弹射飞翼', 'W－ウィング・カタパルト', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1300, 1500, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只「V-喷气虎」为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：装备怪兽的攻击力·守备力上升400。'),
(12607053, 'Waboku', '和睦使者', '和睦の使者', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，自己怪兽不会被战斗破坏，自己受到的战斗伤害变成0。'),
(54807656, 'Wailing of the Unchained Souls', '破械神的恸哭', '破械神の慟哭', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己对「破械」连接怪兽的连接召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：盖放的这张卡被效果破坏的场合才能发动。从卡组把1只「破械」怪兽特殊召唤。'),
(85586937, 'WAKE CUP! Earl', '威咖杯！格雷', 'WAKE CUP！ アル', 'Flip Effect Monster', 'Aqua', 'WIND', 7, 2700, 400, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。从自己手卡选1只其他的反转怪兽丢弃，这张卡表侧攻击表示或里侧守备表示特殊召唤。 ②：这张卡反转的场合才能发动。把最多有自己场上的反转怪兽数量的对方场上的表侧表示卡送去墓地。 ③：自己结束阶段，以自己墓地1只反转怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。'),
(6361316, 'WAKE CUP! Kuro', NULL, NULL, 'Flip Effect Monster', 'Aqua', 'WIND', 7, 400, 2700, NULL),
(71410542, 'WAKE CUP! Macchia', '威咖杯！玛奇', 'WAKE CUP！ マキ', 'Flip Effect Monster', 'Aqua', 'WIND', 3, 1000, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡和手卡1只反转怪兽给对方观看才能发动。那2只里侧守备表示特殊召唤。 ②：这张卡反转的场合，以场上1只里侧守备表示怪兽为对象发动。那只怪兽变成表侧攻击表示。 ③：自己结束阶段，以场上1张里侧表示卡为对象才能发动。那张卡送去墓地。'),
(91818544, 'WAKE CUP! Mocha', '威咖杯！摩卡', 'WAKE CUP！ モカ', 'Flip Effect Monster', 'Aqua', 'WIND', 3, 1000, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只里侧守备表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽变成表侧攻击表示。 ②：这张卡反转的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽攻击力上升1000，结束阶段送去墓地。 ③：自己结束阶段才能发动。这张卡变成里侧守备表示。'),
(92907248, 'Wake Up Centur-Ion!', '觉醒吧・百夫骑士！', 'ウェイクアップ・センチュリオン！', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的魔法与陷阱区域有表侧表示怪兽卡存在的场合，宣言4或8的等级才能发动。把持有宣言的等级的1只「百夫长骑士衍生物」（炎族·暗·攻/守0）在自己场上特殊召唤。这衍生物不能作为融合·连接素材。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把「觉醒吧百夫长骑士！」以外的1张「百夫长骑士」卡送去墓地。'),
(32828466, 'Wake Up Your Elemental HERO', '唤醒你的元素－英雄', 'Wake Up Your E・HERO', 'Fusion Monster', 'Warrior', 'LIGHT', 10, 2500, 2100, '「元素英雄」融合怪兽＋战士族怪兽1只以上 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力上升作为这张卡的融合素材的怪兽数量×300，同1次的战斗阶段中可以向怪兽作出最多有那之内的所用融合怪兽数量的攻击。 ②：这张卡和怪兽进行战斗的伤害计算后发动。那只怪兽破坏，给与对方那个原本攻击力数值的伤害。 ③：融合召唤的这张卡被破坏的场合发动。从手卡·卡组把1只战士族怪兽特殊召唤。'),
(10813327, 'Waking the Dragon', '打草蛇', 'やぶ蛇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：盖放的这张卡因对方的效果从场上离开，被送去墓地的场合或者被除外的场合才能发动。从卡组·额外卡组把1只怪兽特殊召唤。'),
(58169731, 'Wall of Disruption', '分断之壁', '分断の壁', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方场上的全部攻击表示怪兽的攻击力下降对方场上的怪兽数量×800。'),
(13945283, 'Wall of Illusion', '幻影壁', '幻影の壁', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1850, '向这张卡攻击的怪兽回到持有者手卡。伤害计算适用。'),
(30069398, 'Wall of Ivy', '常春藤壁', 'アイヴィ・ウォール', 'Flip Effect Monster', 'Plant', 'EARTH', 2, 300, 1200, '反转：在对方场上把1只「常春藤衍生物」（地·1星·植物族·攻/守0）守备表示特殊召唤。「常春藤衍生物」被破坏时，这衍生物的控制者受到300分伤害。'),
(17078030, 'Wall of Revealing Light', '光之护封壁', '光の護封壁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '支付1000的倍数的基本分发动。只要这张卡在场上存在，持有支付的数值以下的攻击力的对方怪兽不能攻击。'),
(2779999, 'Wall of Thorns', '棘之壁', '棘の壁', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的植物族怪兽被选择作为攻击对象时才能发动。对方场上存在的攻击表示怪兽全部破坏。'),
(63162310, 'Wall Shadow', '墙壁之影', 'ウォール・シャドウ', 'Effect Monster', 'Warrior', 'DARK', 7, 1600, 3000, '不用「迷宫变化」的效果不能特殊召唤。'),
(26984177, 'Walls of the Imperial Tomb', '王墓之石壁', '王墓の石壁', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡只要在场地区域存在，卡名当作「王之棺」使用。 ②：自己主要阶段才能发动。从卡组把1只「荷鲁斯」怪兽加入手卡。那之后，选自己1张手卡回到卡组最下面。 ③：自己把「荷鲁斯之黑炎神」的效果发动的场合才能发动。自己抽1张。'),
(15629802, 'Waltz Token', '武斗圆舞', '武闘円舞', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(2563463, 'Wandering Gryphon Rider', '流离的狮鹫骑士', '流離のグリフォンライダー', 'Effect Monster', 'Winged Beast', 'WIND', 7, 2000, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合或者有「勇者衍生物」存在的场合，自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「勇者衍生物」存在，魔法·陷阱·怪兽的效果发动时才能发动。这张卡回到持有者卡组，那个发动无效并破坏。'),
(52589809, 'Wandering King Wildwind', '风来王 狂风', '風来王 ワイルド・ワインド', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, 1300, '①：自己场上有攻击力1500以下的恶魔族调整存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从卡组把1只攻击力1500以下的恶魔族调整加入手卡。'),
(42994702, 'Wandering Mummy', '彷徨的木乃伊', 'さまようミイラ', 'Effect Monster', 'Zombie', 'EARTH', 4, 1500, 1500, '这张卡1个回合可以有1次变回里侧守备表示。这个效果使用后，把自己的主要怪兽区域的全部里侧守备表示的怪兽洗切，再次重新里侧守备表示按自己的顺序安排到场上的位置。'),
(43363035, 'Wandering Titan of Tartarus', '塔尔塔牢斯的徊神', '地下牢の徊神', 'Effect Monster', 'Zombie', 'EARTH', 9, 2600, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡从卡组送去墓地的场合发动（双方不能对应这个效果的发动把怪兽的效果发动）。自己场上的卡全部送去墓地，这张卡特殊召唤。那之后，把最多有这个效果送去墓地的卡数量的对方场上的卡送去墓地。 ②：这张卡从卡组以外送去墓地的场合，把1张手卡送去墓地才能发动。场上1张卡送去墓地。'),
(3248469, 'Wannabee!', '陷望蜜蜂！', 'ワナビー！', 'Effect Monster', 'Insect', 'LIGHT', 2, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：自己·对方的结束阶段，把手卡·场上的这张卡送去墓地才能发动。把没有使用的对方的魔法与陷阱区域数量的卡从自己卡组上面翻开。可以从那之中选1张陷阱卡在自己场上盖放。剩下的卡用喜欢的顺序回到卡组下面。这个效果盖放的卡在下次的结束阶段送去墓地。'),
(80845034, 'WANTED: Seeker of Sinful Spoils', '“狩猎罪宝的魔鬼”', '“罪宝狩りの悪魔”', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的卡组·墓地把1只「迪亚贝尔斯塔尔」怪兽加入手卡。 ②：自己主要阶段把墓地的这张卡除外，以「“罪宝狩猎之恶魔”」以外的自己的墓地·除外状态的1张「罪宝」魔法·陷阱卡为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。'),
(18558867, 'War Rock Bashileos', '战吼斗士·巴西莱奥斯', 'ウォークライ・バシレオス', 'Effect Monster', 'Warrior', 'EARTH', 8, 2700, 2700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己的战士族·地属性怪兽被战斗破坏时才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：自己的战士族·地属性怪兽进行过战斗的自己·对方的战斗阶段才能发动。自己场上的全部「战吼」怪兽的攻击力直到对方回合结束时上升200。这个回合，这张卡可以直接攻击。'),
(46660187, 'War Rock Big Blow', '战吼大打击', 'ウォークライ・ビッグブロウ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，自己场上的表侧表示的「战吼」怪兽因对方的效果从场上离开的场合才能发动。选对方场上最多2张卡破坏。'),
(47882774, 'War Rock Dignity', '战吼威严', 'ウォークライ・ディグニティ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「战吼」怪兽存在的场合，可以从以下效果选择1个发动。 ●对方场上的怪兽把效果发动时才能发动。那个效果无效。 ●自己·对方的战斗阶段，对方把怪兽的效果·魔法·陷阱卡发动时才能发动。那个效果无效。'),
(83286340, 'War Rock Fortia', '战吼斗士·福蒂亚', 'ウォークライ・フォティア', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的战士族·地属性怪兽进行战斗的伤害计算后才能发动。从卡组把「战吼斗士·福蒂亚」以外的1张「战吼」卡加入手卡。那之后，自己场上的全部「战吼」怪兽的攻击力直到对方回合结束时上升200。 ②：这张卡被对方的效果从怪兽区域送去墓地的场合才能发动。从手卡·卡组把1只5星以上的「战吼」怪兽特殊召唤。'),
(19771459, 'War Rock Gactos', '战吼斗士·加托斯', 'ウォークライ・ガトス', 'Effect Monster', 'Warrior', 'EARTH', 4, 1900, 1900, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有战士族·地属性怪兽召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被对方的效果从怪兽区域送去墓地的场合才能发动。从手卡·卡组把1只5星以上的「战吼」怪兽特殊召唤。'),
(19275188, 'War Rock Generations', '战吼造育', 'ウォークライ・ジェネレート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，自己·对方的战斗阶段才能发动。从卡组把1只「战吼」怪兽特殊召唤。这张卡在对方回合发动的场合，这个回合只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，对方只能向那只怪兽攻击。'),
(84903021, 'War Rock Mammud', '战吼斗士·猛穆德', 'ウォークライ・マムード', 'Effect Monster', 'Warrior', 'EARTH', 5, 2000, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽不存在的场合或者只有战士族怪兽的场合，这张卡可以不用解放作召唤。 ②：自己的战士族·地属性怪兽进行战斗的伤害计算后，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。那之后，自己场上的全部「战吼」怪兽的攻击力直到对方回合结束时上升200。'),
(81613061, 'War Rock Medium', '战吼灵媒', 'ウォークライ・ミーディアム', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要特殊召唤的怪兽在对方场上存在并在自己场上有7星以上的「战吼」怪兽存在，双方的主要阶段1内，双方不能把场上的怪兽的效果发动。 ②：自己主要阶段才能发动。从卡组选「战吼灵媒」以外的1张「战吼」魔法·陷阱卡在自己场上盖放。这个效果的发动后，直到回合结束时自己不是战士族怪兽不能特殊召唤。'),
(10497636, 'War Rock Meteoragon', '战吼斗士·迈泰奥拉贡', 'ウォークライ・メテオラゴン', 'Effect Monster', 'Warrior', 'EARTH', 7, 2600, 2600, '①：这张卡不会被对方的效果破坏。 ②：这张卡和对方怪兽进行战斗的攻击宣言时才能发动。这个回合，那只对方怪兽以及原本卡名和那只对方怪兽相同的怪兽的效果无效化。 ③：1回合1次，自己的战士族·地属性怪兽进行过战斗的自己·对方的战斗阶段才能发动。自己场上的全部「战吼」怪兽的攻击力直到对方回合结束时上升200。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(45943516, 'War Rock Mountain', '战吼的奇岩', 'ザ・ロック・オブ・ウォークライ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「战吼」怪兽加入手卡。 ②：自己场上的怪兽不存在的场合或者只有战士族怪兽的场合，自己·对方的战斗阶段开始时才能发动。同名卡不在自己场上存在的1只「战吼」怪兽从手卡特殊召唤。 ③：自己的战士族怪兽被战斗破坏的场合，可以作为代替把这张卡送去墓地。'),
(71331215, 'War Rock Ordeal', '战吼试炼', 'ウォークライ・オーディール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「战吼试炼」在自己场上只能有1张表侧表示存在。 ②：作为这张卡的发动时的效果处理，给这张卡放置3个指示物。 ③：自己的「战吼」怪兽战斗破坏对方怪兽送去对方墓地时才能发动。这张卡1个指示物取除，自己从卡组抽1张。这个效果让这张卡的指示物全部被取除的场合，这张卡送去墓地。'),
(46169154, 'War Rock Orpis', '战吼斗士·奥菲斯', 'ウォークライ・オーピス', 'Effect Monster', 'Warrior', 'EARTH', 5, 2100, 2100, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽不存在的场合或者只有战士族怪兽的场合，这张卡可以不用解放作召唤。 ②：自己的战士族·地属性怪兽进行战斗的伤害计算后才能发动。从卡组把「战吼斗士·奥菲斯」以外的1只战士族·地属性怪兽送去墓地。那之后，自己场上的全部「战吼」怪兽的攻击力直到对方回合结束时上升200。'),
(72554862, 'War Rock Skyler', '战吼斗士·丝姬拉', 'ウォークライ・スキーラ', 'Effect Monster', 'Warrior', 'EARTH', 6, 2200, 2200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升对方场上的怪兽数量×100。 ②：自己的战士族·地属性怪兽进行过战斗的自己·对方的战斗阶段，以自己墓地1只5星以下的战士族怪兽为对象才能发动。那只怪兽特殊召唤。自己场上的全部「战吼」怪兽的攻击力直到对方回合结束时上升200。这个回合，自己不能用5星以下的怪兽直接攻击。'),
(83880473, 'War Rock Spirit', '战吼精神', 'ウォークライ・スピリッツ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的战斗阶段可以以自己墓地1只「战吼」怪兽为对象，从以下效果选择1个发动。 ●作为对象的怪兽攻击表示特殊召唤。这个效果特殊召唤的怪兽在这个回合效果无效化，不能直接攻击。 ●作为对象的怪兽守备表示特殊召唤。这个回合，自己的「战吼」怪兽各有1次不会被战斗破坏。'),
(47504322, 'War Rock Wento', '战吼斗士·温托', 'ウォークライ・ウェント', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的战士族·地属性怪兽和对方怪兽进行战斗的伤害计算时，支付800基本分才能发动。那只进行战斗的自己怪兽的攻击力直到回合结束时上升800。 ②：这张卡被对方的效果从怪兽区域送去墓地的场合才能发动。从手卡·卡组把1只5星以上的「战吼」怪兽特殊召唤。'),
(54539105, 'War-Lion Ritual', '狮子的仪式', 'ライオンの儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「超级战狮」的降临必需。必须从手卡·自己场上把等级合计直到7以上的怪兽解放。'),
(18482591, 'Warlock of the Ice Barrier', '冰结界的破术师', '氷結界の破術師', 'Effect Monster', 'Spellcaster', 'WATER', 3, 400, 1000, '①：只要自己场上有其他的「冰结界」怪兽存在，双方魔法卡若不盖放则不能发动，直到从盖放的玩家来看的下次的自己回合到来不能发动。'),
(16751086, 'Warm Worm', '暖虫', 'ウォーム・ワーム', 'Effect Monster', 'Insect', 'FIRE', 3, 600, 1400, '①：这张卡被破坏的场合发动。从对方卡组上面把3张卡送去墓地。'),
(11429811, 'Warning Point', '警告点', 'ワーニングポイント', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：怪兽召唤·反转召唤·特殊召唤时才能发动。这个回合，那些表侧表示怪兽不能攻击，效果无效化，不能作为融合·同调·超量·连接召唤的素材。'),
(75953262, 'Warrior Dai Grepher', '战士 戴・古雷法', '戦士ダイ・グレファー', 'Normal Monster', 'Warrior', 'EARTH', 4, 1700, 1600, '隐藏着操纵龙族才能的战士。其过去被迷所包围着。'),
(90873992, 'Warrior Elimination', '战士抹杀', '戦士抹殺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的战士族怪兽全部破坏。'),
(5438492, 'Warrior Lady of the Wasteland', '荒野的女战士', '荒野の女戦士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1100, 1200, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的战士族·地属性怪兽攻击表示特殊召唤。'),
(43797906, 'Warrior of Atlantis', '亚特兰蒂斯的战士', 'アトランティスの戦士', 'Effect Monster', 'Aqua', 'WATER', 4, 1900, 1200, '①：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「传说之都 亚特兰蒂斯」加入手卡。'),
(56413937, 'Warrior of Tradition', '战场的死装束', '戦場の死装束', 'Fusion Monster', 'Warrior', 'EARTH', 6, 1900, 1700, '「音女」＋「斩首的美女」'),
(66073051, 'Warrior of Zera', '杰拉的战士', 'ゼラの戦士', 'Normal Monster', 'Warrior', 'EARTH', 4, 1600, 1600, '听闻抵达圣域可得大天使力量，故而寻找此地的战士。为了逃离邪恶的魔族诱惑，过着只身作战的孤独日子。'),
(23424603, 'Wasteland', '荒野', '荒野', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部恐龙族·不死族·岩石族的怪兽攻击力·守备力上升200。'),
(87774234, 'Watapon', '棉花球', 'ワタポン', 'Effect Monster', 'Fairy', 'LIGHT', 1, 200, 300, '这张卡被魔法·陷阱·效果怪兽的效果从自己卡组加入手卡的场合，这张卡可以在自己场上特殊召唤。'),
(70975131, 'Watch Cat', '番猫-戴表看门猫', '番猫－ウォッチキャット', 'Effect Monster', 'Beast', 'EARTH', 1, NULL, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的自己回合的结束阶段把场上的这张卡除外才能发动。从卡组选1张永续魔法卡在自己的魔法与陷阱区域盖放。'),
(86889202, 'Watch Dog', '番犬-戴表看门狗', '番犬－ウォッチドッグ', 'Effect Monster', 'Pyro', 'FIRE', 1, NULL, NULL, '「番犬-戴表看门狗」的效果1回合只能使用1次，这个效果发动的回合，自己不能把怪兽特殊召唤。 ①：这张卡召唤成功的回合的主要阶段2把手卡1张魔法卡送去墓地才能发动。从卡组选1张永续魔法卡在自己的魔法与陷阱区域盖放。'),
(85066822, 'Water Dragon', '水龙', 'ウォーター・ドラゴン', 'Effect Monster', 'Sea Serpent', 'WATER', 8, 2800, 2600, '这张卡不能通常召唤，用「结合术-H2O」的效果才能特殊召唤。 ①：只要这张卡在怪兽区域存在，场上的炎属性怪兽以及炎族怪兽的攻击力变成0。 ②：这张卡被破坏送去墓地时，以自己墓地2只「氢素龙」和1只「氧素龙」为对象才能发动。那些怪兽特殊召唤。'),
(6022371, 'Water Dragon Cluster', '水龙-团簇', 'ウォーター・ドラゴン－クラスター', 'Effect Monster', 'Sea Serpent', 'WATER', 10, 2800, 2600, '这张卡不能通常召唤。「结合术」魔法·陷阱卡的效果才能特殊召唤。 ①：这张卡特殊召唤成功的场合才能发动。对方场上的效果怪兽直到回合结束时攻击力变成0，不能把效果发动。 ②：把这张卡解放才能发动。从手卡·卡组把2只「水龙」无视召唤条件守备表示特殊召唤。这个效果在对方回合也能发动。'),
(3732747, 'Water Element', '水元素', 'ウォーター・エレメント', 'Normal Monster', 'Aqua', 'WATER', 3, 900, 700, '住在水里的精灵。将四周用雾包围妨碍敌人的视线。'),
(30680659, 'Water Enchantress of the Temple', '圣殿的遣水士', '聖殿の水遣い', 'Effect Monster', 'Spellcaster', 'WATER', 3, 1500, 1200, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有「勇者衍生物」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把手卡·墓地的这张卡除外才能发动。从自己的卡组·墓地把1张「阿拉弥赛亚之仪」加入手卡。 ③：自己场上有「勇者衍生物」存在的场合才能发动。把有「勇者衍生物」的衍生物名记述的1张场地魔法卡从卡组到自己场上表侧表示放置。'),
(55014050, 'Water Girl', '水之少女', 'ウォーター・ガール', 'Normal Monster', 'Aqua', 'WATER', 4, 1250, 1000, '用水像冰箭般攻击的美丽姐姐。'),
(49669730, 'Water Hazard', '水障', 'ウォーターハザード', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上没有怪兽存在的场合，可以从手卡把1只4星以下的水属性怪兽特殊召唤。这个效果1回合只能使用1次。'),
(37061511, 'Water Leviathan @Ignister', '水勒维亚坦＠伊格尼斯者', 'ウォーターリヴァイアサン＠イグニスター', 'Ritual Effect Monster', 'Cyberse', 'WATER', 7, 2300, 2000, '「“艾”之仪式」降临。这个卡名的②的效果1回合只能使用1次。 ①：这张卡仪式召唤成功的场合才能发动。对方场上的攻击力2300以下的怪兽全部回到持有者手卡。 ②：以对方场上1只表侧表示怪兽为对象才能发动。自己墓地的连接怪兽全部回到额外卡组，作为对象的怪兽的攻击力变成0。 ③：这张卡和对方怪兽进行战斗的伤害计算时才能发动1次。那只对方怪兽的攻击力只在那次伤害计算时变成一半。'),
(93343894, 'Water Magician', '水之魔导师', '水の魔導師', 'Normal Monster', 'Aqua', 'WATER', 4, 1400, 1000, '用水裹住对方并包围着施以攻击。'),
(7133305, 'Water of Life', '活命水', '命の水', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上没有怪兽存在的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽攻击表示特殊召唤。这张卡的发动后，直到回合结束时自己不能把这个效果特殊召唤的场上的怪兽以外的怪兽的效果发动。'),
(2483611, 'Water Omotics', '水之舞女', '水の踊り子', 'Normal Monster', 'Aqua', 'WATER', 4, 1400, 1200, '从瓶中不断流淌的水，变成龙的形状发动攻击。'),
(487395, 'Water Spirit', '水灵', 'ウォーター・スピリット', 'Normal Tuner Monster', 'Aqua', 'WATER', 1, 400, 1200, '据说是在古代南极大陆的永久冻土拥有了生命的冰水精灵。能够渗透进各种物质里。'),
(66836598, 'Waterdragon Fairy', '温蒂妮', 'ウンディーネ', 'Normal Monster', 'Aqua', 'WATER', 3, 1100, 700, '在水中摇摇晃晃漂浮的妖精。好像可以召唤水龙。'),
(23068051, 'Waterfall of Dragon Souls', '幽丽幻泷', '幽麗なる幻滝', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●从卡组把1只幻龙族怪兽加入手卡。 ●从手卡以及自己场上的表侧表示怪兽之中把幻龙族怪兽任意数量送去墓地才能发动。自己从卡组抽出送去墓地的怪兽的数量＋1张。'),
(87151205, 'Wattaildragon', '电力尾龙', 'エレキテルドラゴン', 'Normal Monster', 'Dragon', 'LIGHT', 6, 2500, 1000, '总有电气缠绕的空中浮游之龙。从古代就存在，其生态还有很多的谜，但由于古之规则而禁止捕获。'),
(5554990, 'Wattberyx', '电气金眼鲷', 'エレキンメダイ', 'Tuner Monster', 'Thunder', 'LIGHT', 3, 300, NULL, '这张卡直接攻击给与对方基本分战斗伤害时，对方手卡随机丢弃1张。'),
(18407024, 'Wattbetta', '电气金鱼', 'エレキンギョ', 'Tuner Monster', 'Thunder', 'LIGHT', 2, 100, NULL, '这张卡直接攻击给与对方基本分战斗伤害时，对方选择1张手卡丢弃。'),
(56993276, 'Wattcancel', '电力抵消', 'エレキャンセル', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '从手卡丢弃1只名字带有「电气」的怪兽发动。对方怪兽的召唤·特殊召唤无效并破坏。'),
(95084054, 'Wattcannon', '电气大炮', 'エレキャノン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '场上有4星以下的雷族怪兽召唤·特殊召唤时，给与对方基本分600分伤害。这个效果1回合只能使用1次。'),
(58924378, 'Wattcastle', '电气城堡', 'エレキャッスル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，向名字带有「电气」的怪兽攻击的怪兽的攻击力在那次伤害计算后下降1000。'),
(2772236, 'Wattchimera', '电力客迈拉', 'エレキマイラ', 'Synchro Monster', 'Thunder', 'LIGHT', 6, 1400, 1200, '名字带有「电气」的调整＋调整以外的雷族怪兽1只以上 这张卡可以直接攻击对方玩家。这张卡直接攻击给与对方基本分战斗伤害时，对方手卡随机1张到卡组最上面放置。'),
(1834107, 'Wattcine', '电气治疗', 'エレキュア', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上存在的雷族怪兽给与对方基本分战斗伤害时，自己基本分回复给与的战斗伤害的数值。'),
(88205593, 'Wattcobra', '电力眼镜王蛇', 'エレキングコブラ', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1000, 500, '这张卡可以直接攻击对方玩家。这张卡直接攻击给与对方基本分战斗伤害时，从自己卡组把1只名字带有「电气」的怪兽加入手卡。'),
(65612454, 'Wattcube', '电气立方体', 'エレキューブ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '雷族怪兽才能装备。装备怪兽的攻击力上升自己墓地存在的雷族怪兽数量×100的数值。此外，可以把场上表侧表示存在的这张卡送去墓地，自己场上表侧表示存在的1只雷族怪兽的攻击力上升1000。'),
(97885363, 'Wattdragonfly', '电力蜻蜓', 'エレキトンボ', 'Effect Monster', 'Thunder', 'LIGHT', 2, 900, 100, '这张卡被对方破坏的场合，可以从自己卡组把1只名字带有「电气」的怪兽特殊召唤。'),
(46897277, 'Wattfox', '电力狐狸', 'エレキツネ', 'Tuner Monster', 'Thunder', 'LIGHT', 2, 800, 100, '这张卡被对方破坏的场合，那个回合对方不能作怪兽的特殊召唤以及把魔法·陷阱·效果怪兽的效果发动。'),
(402568, 'Wattgiraffe', '电力长颈鹿', 'エレキリン', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1200, 100, '①：这张卡可以直接攻击。 ②：这张卡直接攻击给与对方战斗伤害的场合发动。这个回合，对方不能把魔法·陷阱·怪兽的效果发动。'),
(61380658, 'Watthopper', '电力螽斯', 'エレキリギリス', 'Effect Monster', 'Thunder', 'LIGHT', 1, NULL, NULL, '只要这张卡在场上表侧表示存在，对方不能选择表侧表示存在的其他的名字带有「电气」的怪兽作为攻击对象，也不能作为卡的效果的对象。'),
(29765339, 'Watthydra', '电力七头兽', 'エレキリム', 'Synchro Monster', 'Thunder', 'LIGHT', 7, 1500, 1500, '「电气」调整＋调整以外的雷族怪兽1只以上 ①：这张卡可以直接攻击。 ②：这张卡直接攻击给与对方战斗伤害的场合发动。从卡组选1张卡除外。发动后第2次的自己准备阶段，这个效果除外的卡加入手卡。'),
(84428023, 'Wattjustment', '电气存储枪', 'エレキャッシュ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '3星以下的雷族怪兽才能装备。装备怪兽的攻击力上升800，效果无效化。装备怪兽给与对方基本分战斗伤害时，从自己卡组抽1张卡。'),
(32061744, 'Wattkeeper', '电气看守', 'エレキーパー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只4星以下的名字带有「电气」的怪兽发动。选择的怪兽从墓地特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段时破坏。'),
(53193261, 'Wattkey', '电气钥匙', 'エレキー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「电气」的怪兽在这个回合可以直接攻击对方玩家。'),
(27324313, 'Wattkid', '电力小子', 'エレキッズ', 'Normal Monster', 'Thunder', 'LIGHT', 3, 1000, 500, '雷属性攻击异常厉害，若轻视它则会遭到电击。'),
(88392300, 'Wattkinetic Puppeteer', '电送拟人 电力念动', '電送擬人エレキネシス', 'Effect Monster', 'Psychic', 'LIGHT', 4, 1800, NULL, '①：把手卡·场上的这张卡送去墓地，以对方场上1只怪兽为对象才能发动。那只对方怪兽的位置向其他的对方的主要怪兽区域移动。这个效果在对方回合也能发动。'),
(41790641, 'Wattkingdom', '电力王国', 'エレキングダム', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方不能把位于这张卡以及自己场上的「电气」怪兽的正对面的对方怪兽自身的召唤·特殊召唤成功时的效果发动。 ②：以自己场上1只「电气」怪兽为对象才能发动。和那只怪兽卡名不同的1只「电气」怪兽从卡组特殊召唤。那之后，自己失去这个效果特殊召唤的怪兽的攻击力数值的基本分。这个效果的发动后，直到回合结束时自己不是雷族怪兽不能特殊召唤。'),
(24996659, 'Wattkiwi', '电气鹬鸵', 'エレキーウィ', 'Tuner Monster', 'Thunder', 'LIGHT', 3, 600, 100, '只要这张卡在场上表侧表示存在，自己场上存在的名字带有「电气」的怪兽攻击的场合，攻击怪兽不会被战斗破坏。'),
(67752972, 'Wattkyuki', '电力穷奇', 'エレキュウキ', 'Synchro Monster', 'Thunder', 'LIGHT', 8, 1600, 1700, '「电气」调整＋调整以外的雷族怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡可以直接攻击。 ②：这张卡直接攻击给与对方战斗伤害时才能发动。自己墓地的「电气」调整1只和调整以外的自己场上的表侧表示的雷族怪兽1只回到卡组，从额外卡组把「电气穷奇」以外的1只「电气」同调怪兽特殊召唤。'),
(45801022, 'Wattlemur', '电气狐猴', 'エレキツネザル', 'Effect Monster', 'Thunder', 'LIGHT', 2, 800, 100, '这张卡被对方破坏的场合，下次的对方回合，对方不能进行战斗阶段。'),
(32548609, 'Wattmole', '电气金毛鼹', 'エレキンモグラ', 'Effect Monster', 'Thunder', 'LIGHT', 3, NULL, 100, '这张卡在同1次的战斗阶段中可以作2次攻击。这张卡向里侧守备表示怪兽攻击的场合，可以不进行伤害计算以里侧守备表示的状态把那只怪兽破坏。'),
(81896771, 'Wattpheasant', '电力绿雉', 'エレキジ', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1000, 800, '这张卡可以直接攻击对方玩家。这张卡直接攻击给与对方基本分战斗伤害时，选择场上表侧表示存在的1只怪兽，直到这个回合的结束阶段时从游戏中除外。'),
(56577312, 'Wattrain', '电力机关车', 'エレキカンシャ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把最多有自己场上的雷族怪兽种类数量的「电气机车」以外的「电气」卡从卡组加入手卡（同名卡最多1张）。 ②：把墓地的这张卡除外才能发动。从手卡把「电气」怪兽尽可能特殊召唤（同名卡最多1张）。这个效果在这张卡送去墓地的回合不能发动。'),
(23274061, 'Wattsquirrel', '电气红松鼠', 'エレキタリス', 'Effect Monster', 'Thunder', 'LIGHT', 3, 700, 100, '这张卡在同1次的战斗阶段中可以作2次攻击。和这张卡进行战斗的效果怪兽的效果在伤害计算后无效化。'),
(81028112, 'Wattsychic Fighter', '电气念力斗士', 'エレキック・ファイター', 'Effect Monster', 'Psychic', 'LIGHT', 3, 1500, 300, '「电气念力斗士」的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时，以对方墓地1张卡为对象才能发动。那张卡回到对方卡组最上面或者最下面。'),
(51303014, 'Wattsychic Fighting Porter', '电气念力战斗传送士', 'エレキック・ファイティング・ポーター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡把最多2只3星以下的光属性怪兽特殊召唤。这个效果把原本种族相同的2只怪兽特殊召唤的场合，这个回合，那些怪兽可以直接攻击。这个效果把原本等级相同的2只怪兽特殊召唤的场合，这个回合，那些怪兽不会被战斗破坏。'),
(10113611, 'Wattuna', '电力黄鳍金枪鱼', 'エレキハダマグロ', 'Tuner Monster', 'Thunder', 'LIGHT', 4, 800, 700, '这个卡名的①③的效果1回合各能使用1次。 ①：自己怪兽给与对方战斗伤害的伤害步骤结束时才能发动。这张卡从手卡特殊召唤。 ②：这张卡可以直接攻击。 ③：这张卡直接攻击给与对方战斗伤害时才能发动。这张卡和除调整以外的自己的手卡·场上（表侧表示）的怪兽1只以上解放，把持有和解放的怪兽的等级合计相同等级的1只「电气」同调怪兽从额外卡组特殊召唤。'),
(12296376, 'Wattwoodpecker', '电气啄木鸟', 'エレキツツキ', 'Effect Monster', 'Thunder', 'LIGHT', 3, 1000, 100, '这张卡在同1次的战斗阶段中可以作2次攻击。和这张卡进行过战斗的怪兽不能把表示形式变更。'),
(38992735, 'Wave-Motion Cannon', '波动加农炮', '波動キャノン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。给与对方这张卡的发动后经过的自己准备阶段次数×1000伤害。'),
(63665606, 'Wave-Motion Inferno', '虚无的波动', '虚無の波動', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己没有手卡时，自己场上表侧表示存在的名字带有「永火」的怪兽攻击力及守备力增加400。可以把自己场上表侧表示存在的这张卡送去墓地将自己的所有手卡送去墓地。'),
(31222701, 'Wavering Eyes', '摇摆的视线', '揺れる眼差し', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：双方的灵摆区域的卡全部破坏。那之后，这个效果破坏的卡数量的以下效果适用。 ●1张以上：给与对方500伤害。 ●2张以上：可以从卡组把1只灵摆怪兽加入手卡。 ●3张以上：可以选场上1张卡除外。 ●4张：可以从卡组把1张「摇晃的目光」加入手卡。'),
(91880660, 'Way Where There''s a Will', '九死必有一生路', '仇すれば通図', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：双方玩家在自己主要阶段才能发动。把最多有对方场上的卡数量的卡从自己卡组上面翻开，从那之中选1张加入手卡。那之后，剩下的卡以及自己1张手卡用喜欢的顺序回到卡组下面。 ②：这张卡的①的效果是1次有9张以上翻开的玩家在那个回合的结束阶段才能发动。对方的场上·墓地的卡全部回到卡组。'),
(10035717, 'Weapon Change', '武器交换', 'ウェポンチェンジ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '此效果只能在自己每回合的准备阶段支付700基本分发动1次。使自己场上1只战士族·机械族怪兽的攻击力与守备力互换直到对方的下一个结束阶段终了时为止。当这张卡被破坏时，此效果无效化。'),
(37243151, 'Weather Control', '气象控制员', 'ウェザー・コントロール', 'Normal Monster', 'Fairy', 'LIGHT', 2, 600, 400, '可以自由操纵天气。山里的天气无常就是这家伙的杰作。'),
(72053645, 'Weather Report', '气象报告员', 'ウェザー・レポート', 'Flip Effect Monster', 'Aqua', 'WATER', 4, 950, 1500, '反转：对方场上表侧表示存在的「光之护封剑」全部破坏。破坏成功的场合，下次的自己的战斗阶段可以进行2次。'),
(23147658, 'Weathering Soldier', '风化战士', '風化戦士', 'Effect Monster', 'Rock', 'EARTH', 4, 2000, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡被效果送去墓地的场合或者被战斗破坏的场合才能发动。把1张「风化战士」以外的有「化石融合」的卡名记述的卡或者「化石融合」从卡组加入手卡。 ②：自己结束阶段发动。这张卡的攻击力下降600。'),
(78021082, 'Weaver of Fairy Tail Tales', NULL, NULL, 'Fusion Monster', 'Spellcaster', 'EARTH', 4, 1850, 1000, NULL),
(63017368, 'Wedju Temple', '石版神殿', '石版の神殿', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从手卡把1只怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。那之后，把1只「千年」怪兽从卡组当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：自己场上的表侧表示的「千年」怪兽被战斗·效果破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(71384012, 'Wee Witch''s Apprentice', '见习魔娘', '見習い魔嬢', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1400, NULL, '暗属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：场上的暗属性怪兽的攻击力·守备力上升500，光属性怪兽的攻击力·守备力下降400。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只暗属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(28604635, 'Weed Out', '抖落', 'ふるい落とし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分。场上表侧攻击表示存在的全部3星的怪兽破坏。'),
(81005500, 'Ween, the Spirit of Treats', '点心大精灵 维恩', 'お菓子の大精霊ウィーン', 'Effect Monster', 'Zombie', 'LIGHT', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。这张卡在自己场上表侧表示存在的场合，对方从以下效果选1个，自己让那个效果适用。 ●这张卡的攻击力上升自己墓地的不死族怪兽数量×800。 ●给与对方为自己墓地的不死族怪兽数量×500伤害。 ②：这张卡被战斗·效果破坏的场合才能发动。从对方墓地把1只怪兽在自己场上特殊召唤。');